import type OpenAI from 'openai';
import type { AuditService } from '../audit/audit.service';
import type { PrismaService } from '../prisma/prisma.service';
import type { StructuredLogger } from '../logging/structured-logger';
import type { RiskGateService } from './risk-class/risk-gate.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ToolArgs } from './unified-agent.types';
import type { UnknownRecord } from './unified-agent-core.helpers';

interface UnifiedAgentToolEnvelope {
  id: string;
  toolName: string;
  allowed: boolean;
}

interface ExecuteUnifiedAgentToolActionInput {
  logger: StructuredLogger;
  prisma: PrismaService;
  auditService: AuditService;
  actions: UnifiedAgentActionsService;
  riskGate: RiskGateService | undefined;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
  workspaceId: string;
  contactId: string;
  phone: string;
  tool: string;
  args: ToolArgs;
  context: UnknownRecord | undefined;
  num: (v: unknown, fb?: number) => number;
  buildAgentToolEnvelope: (params: {
    workspaceId: string;
    toolName: string;
  }) => UnifiedAgentToolEnvelope;
}

export async function executeUnifiedAgentToolAction(
  input: ExecuteUnifiedAgentToolActionInput,
): Promise<unknown> {
  const { workspaceId, contactId, phone, tool, args, context } = input;

  input.logger.log(`Executing tool: ${tool}`, { args });
  const envelope = input.buildAgentToolEnvelope({
    workspaceId,
    toolName: tool,
  });

  switch (tool) {
    case 'send_message':
      return input.actions.actionSendMessage(workspaceId, phone, args, context);
    case 'send_product_info':
      return input.actions.actionSendProductInfo(workspaceId, phone, args, context);
    case 'create_payment_link': {
      const paymentAmount = input.num(args.amount);
      if (input.riskGate && paymentAmount > 0) {
        const gateDecision = input.riskGate.gatePaymentAction({
          amountCents: paymentAmount,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          input.logger.error(`R4 BLOCKED: create_payment_link — ${gateDecision.reason}`);
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          input.logger.warn(
            `Risk gate: payment ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      const result = await input.actions.actionCreatePaymentLink(
        workspaceId,
        phone,
        args,
        context,
      );
      try {
        await input.prisma.$transaction(
          async (tx) => {
            await input.auditService.logWithTx(tx, {
              workspaceId,
              action: 'AGENT_DISPATCHED_PAYMENT_LINK',
              resource: 'UnifiedAgent',
              resourceId: contactId,
              details: { tool, phone },
            });
          },
          { isolationLevel: 'ReadCommitted' },
        );
      } catch (auditError: unknown) {
        const auditMsg =
          auditError instanceof Error
            ? auditError.message
            : typeof auditError === 'string'
              ? auditError
              : 'unknown';
        input.logger.warn(`Audit dispatch log failed: ${auditMsg}`);
      }
      return result;
    }
    case 'update_lead_status':
      return input.actions.actionUpdateLeadStatus(workspaceId, contactId, args);
    case 'add_tag':
      return input.actions.actionAddTag(workspaceId, contactId, args);
    case 'schedule_followup':
      return input.actions.actionScheduleFollowup(workspaceId, contactId, phone, args, context);
    case 'transfer_to_human':
      return input.actions.actionTransferToHuman(workspaceId, contactId, args, context);
    case 'search_knowledge_base':
      return input.actions.actionSearchKnowledgeBase(workspaceId, args);
    case 'trigger_flow':
      return input.actions.actionTriggerFlow(workspaceId, phone, args);
    case 'log_event':
      return input.actions.actionLogEvent(workspaceId, contactId, args);
    case 'send_media':
      return input.actions.actionSendMedia(workspaceId, phone, args, context);
    case 'send_document':
      return input.actions.actionSendDocument(workspaceId, phone, args, context);
    case 'send_voice_note':
      return input.actions.actionSendVoiceNote(workspaceId, phone, args, context);
    case 'send_audio':
      return input.actions.actionSendAudio(workspaceId, phone, args, context);
    case 'transcribe_audio':
      return input.actions.actionTranscribeAudio(workspaceId, args);
    case 'create_product':
      return input.actions.actionCreateProduct(workspaceId, args);
    case 'update_product':
      return input.actions.actionUpdateProduct(workspaceId, args);
    case 'get_product_plans':
      return input.actions.getProductPlans(input.actions.str(args.productId));
    case 'get_product_ai_config':
      return input.actions.getProductAIConfig(input.actions.str(args.productId));
    case 'get_product_reviews':
      return input.actions.getProductReviews(input.actions.str(args.productId));
    case 'get_product_urls':
      return input.actions.getProductUrls(input.actions.str(args.productId));
    case 'validate_coupon':
      return input.actions.validateCoupon(
        input.actions.str(args.productId),
        input.actions.str(args.code),
      );
    case 'create_flow':
      return input.actions.actionCreateFlow(workspaceId, args);
    case 'update_workspace_settings':
      return input.actions.actionUpdateWorkspaceSettings(workspaceId, args);
    case 'create_broadcast':
      return input.actions.actionCreateBroadcast(workspaceId, args, context);
    case 'get_analytics':
      return input.actions.actionGetAnalytics(workspaceId, args);
    case 'configure_ai_persona':
      return input.actions.actionConfigureAIPersona(workspaceId, args);
    case 'toggle_autopilot':
      return input.actions.actionToggleAutopilot(workspaceId, args);
    case 'create_flow_from_description':
      return input.actions.actionCreateFlowFromDescription(
        workspaceId,
        args,
        input.openai,
        input.primaryBrainModel,
        input.fallbackBrainModel,
      );
    case 'connect_whatsapp':
      return input.actions.actionConnectWhatsApp(workspaceId, args);
    case 'import_contacts':
      return input.actions.actionImportContacts(workspaceId, args);
    case 'generate_sales_funnel':
      return input.actions.actionGenerateSalesFunnel(workspaceId, args);
    case 'schedule_campaign':
      return input.actions.actionScheduleCampaign(workspaceId, args);
    case 'get_workspace_status':
      return input.actions.actionGetWorkspaceStatus(workspaceId, args);
    case 'update_billing_info':
      return input.actions.actionUpdateBillingInfo(workspaceId, args);
    case 'get_billing_status':
      return input.actions.actionGetBillingStatus(workspaceId);
    case 'change_plan':
      return input.actions.actionChangePlan(workspaceId, args);
    case 'apply_discount':
      if (input.riskGate) {
        const gateDecision = input.riskGate.gateDiscountOffer({
          amountCents: 0,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          input.logger.error(`R4 BLOCKED: apply_discount — ${gateDecision.reason}`);
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          input.logger.warn(
            `Risk gate: discount ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      return input.actions.actionApplyDiscount(workspaceId, contactId, phone, args, context);
    case 'handle_objection':
      return input.actions.actionHandleObjection(workspaceId, contactId, phone, args, context);
    case 'qualify_lead':
      return input.actions.actionQualifyLead(workspaceId, contactId, phone, args, context);
    case 'schedule_meeting':
      return input.actions.actionScheduleMeeting(workspaceId, contactId, phone, args, context);
    case 'anti_churn_action':
      return input.actions.actionAntiChurn(workspaceId, contactId, phone, args, context);
    case 'reactivate_ghost':
      return input.actions.actionReactivateGhost(workspaceId, contactId, phone, args, context);
    default:
      input.logger.warn(`Unknown tool: ${tool}`);
      return { success: false, error: 'Unknown tool', policyEnvelope: envelope };
  }
}

