export async function processUnifiedAgentMessage(
  input: ProcessUnifiedAgentMessageInput,
): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const { workspaceId, contactId, phone, message, context } = input;
  const predecidedActions = input.predecidedActions ?? [];

  if (!input.openai && predecidedActions.length === 0) {
    input.logger.warn('OpenAI not configured');
    return input.response.buildFallbackResult(message);
  }

  const [workspace, contact, conversationHistory, products] = await Promise.all([
    input.ctx.getWorkspaceContext(workspaceId),
    input.ctx.getContactContext(workspaceId, contactId, phone),
    input.ctx.getConversationHistory(workspaceId, contactId, 0, phone),
    input.ctx.getProducts(workspaceId),
  ]);

  const productIds = products
    .map((product: UnknownRecord) => {
      const productValue = input.ctx.readRecord(product.value);
      return input.ctx.readOptionalText(productValue.id) || input.ctx.readOptionalText(product.id);
    })
    .filter((productId): productId is string => Boolean(productId));
  let aiConfigs: UnknownRecord[] = [];
  if (productIds.length > 0) {
    try {
      aiConfigs = await input.prisma.productAIConfig.findMany({
        take: 50,
        where: { productId: { in: productIds } },
        select: {
          id: true,
          productId: true,
          tone: true,
          persistenceLevel: true,
          messageLimit: true,
          customerProfile: true,
          positioning: true,
          objections: true,
          salesArguments: true,
        },
      });
    } catch {
      /* ProductAIConfig may not exist yet */
    }
  }

  const compressedContext = await input.ctx.buildAndPersistCompressedContext(
    workspaceId,
    contactId,
    phone,
    contact,
  );
  const tacticalHint = input.ctx.buildLeadTacticalHint({
    leadName: input.ctx.isRecord(contact) ? input.ctx.readText(contact.name).trim() : '',
    currentMessage: message,
    conversationHistory,
  });

  const agentRuntimeContext = await input.buildAgentRuntimeContext({
    workspaceId,
    channel: input.ctx.readText(context?.channel, 'whatsapp'),
    message,
    contactId,
    ...(input.allowedTools !== undefined ? { allowedTools: input.allowedTools } : {}),
  });
  const systemPrompt = [
    input.ctx.buildSystemPrompt(workspace, products, aiConfigs),
    agentRuntimeContext.systemPromptBlock,
  ].join('\n\n');
  const stylePolicy = input.response.buildReplyStyleInstruction(
    message,
    conversationHistory.length,
  );
  const contactData: Record<string, unknown> = input.ctx.isRecord(contact) ? contact : {};
  const contactName = input.ctx.readText(contactData.name).trim() || phone;
  const contactSentiment = input.ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
  const leadScore = input.ctx.readText(contactData.leadScore, '0');
  const tagNames = input.ctx.readTagList(contactData.tags);

  const additionalContext = context ? formatPromptValue(context) : '';
  const currentInput = {
    raw: message,
    channel: input.ctx.readText(context?.channel, 'whatsapp'),
    arrivalTimestamp: new Date().toISOString(),
  };
  let cognitiveState: Record<string, unknown> = {
    abiStatus: input.abiBuilder ? 'unavailable_or_invalid' : 'builder_not_injected',
    audience: 'public',
    perceptionSnapshot: { channel: currentInput.channel },
  };

  if (input.abiBuilder) {
    const abiResult = await input.abiBuilder.build({
      audience: 'public',
      currentInput,
      perceptionSnapshot: {
        channel: currentInput.channel,
      },
    });

    if (abiResult.status !== 'ok') {
      input.logger.warn(
        `ABI build failed: ${abiResult.reason}, using structured unified agent fallback`,
      );
    } else {
      const abi = abiResult.abi;
      const validation = validateAbiPayload(abi);

      if (validation.status === 'FAIL') {
        input.logger.warn(
          `ABI validation failed: ${JSON.stringify(validation.issues)}, using structured unified agent fallback`,
        );
      } else {
        cognitiveState = abi as unknown as Record<string, unknown>;
      }
    }
  }

  const messages: ChatCompletionMessageParam[] = [
    ...conversationHistory,
    {
      role: 'user',
      content: JSON.stringify({
        cognitiveState,
        runtimeContext: {
          workspaceProductContext: systemPrompt,
          compressedMemory: compressedContext || null,
          additionalContext,
          tacticalHint: tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
          responsePolicy: stylePolicy,
        },
        contact: {
          name: contactName,
          sentiment: contactSentiment,
          leadScore,
          tags: tagNames,
        },
        currentInput,
      }),
    },
  ];

  if (predecidedActions.length > 0) {
    const actionsList = await executePredecidedAgentActions({
      ...(input.allowedTools !== undefined ? { allowedTools: input.allowedTools } : {}),
      contactId,
      ...(context !== undefined ? { context } : {}),
      executeTool: input.executeToolAction,
      logAutopilotEvent: input.actions.logAutopilotEvent.bind(input.actions),
      phone,
      predecidedActions,
      workspaceId,
    });
