  try {
    await input.planLimits.ensureTokenBudget(workspaceId);
    const openai = input.openai;
    if (!openai) {
      const error = new Error();
      error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
      throw error;
    }
    llmResponse = await chatCompletionWithFallback(
      openai,
      {
        model: input.primaryBrainModel,
        messages,
        temperature: 0.82,
        top_p: 0.9,
      },
      input.fallbackBrainModel,
    );
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
    input.logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
    return input.response.buildFallbackResult(message);
  }
  if (!llmResponse) {
    return input.response.buildFallbackResult(message);
  }
  const firstChoice = llmResponse.choices[0];
  if (!firstChoice) {
    return input.response.buildFallbackResult(message);
  }
  await input.planLimits
    .trackAiUsage(workspaceId, llmResponse.usage?.total_tokens ?? 500)
    .catch(() => {});

  const assistantMessage = firstChoice.message;
  const actionsList: ActionEntry[] = [];

  const executeTools = context?.executeTools !== false;
  if (executeTools && assistantMessage.tool_calls && assistantMessage.tool_calls.length > 0) {
    await forEachSequential(assistantMessage.tool_calls, async (toolCall) => {
      if (toolCall.type !== 'function') {
        return;
      }
      const toolName = toolCall.function.name;
      if (!isAllowedUnifiedAgentTool(toolName, input.allowedTools)) {
        input.logger.warn(
          `Blocked disallowed agent tool call: workspaceId=${workspaceId} tool=${toolName}`,
        );
        const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
        actionsList.push({ tool: toolName, args: {}, result: blockedResult });
        await input.actions.logAutopilotEvent(
          workspaceId,
          contactId,
          toolName,
          {},
          blockedResult,
        );
        return;
      }
      let toolArgs: Record<string, unknown> = {};
      try {
        toolArgs = JSON.parse(toolCall.function.arguments || '{}');
      } catch {
        input.logger.warn(`Failed to parse tool args for ${toolName}`);
      }
      const result = await input.executeToolAction(
        workspaceId,
        contactId,
        phone,
        toolName,
        toolArgs,
        context,
      );
      actionsList.push({ tool: toolName, args: toolArgs, result });
      await input.actions.logAutopilotEvent(workspaceId, contactId, toolName, toolArgs, result);
    });
  }

  const intent = input.response.extractIntent(actionsList, message);
  const confidence = input.response.calculateConfidence(actionsList, llmResponse);
  const draftedReply = await input.response.composeWriterReply(
    input.openai,
    input.writerModel,
    input.fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: assistantMessage.content,
      actions: actionsList,
      historyTurns: conversationHistory.length,
    },
  );

  await input.recordAgentRuntimeTurn({
    workspaceId,
    channel: input.ctx.readText(context?.channel, 'whatsapp'),
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: input.actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence,
  };
}

