  actions: UnifiedAgentActionsService;
  logger: StructuredLogger;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
  writerModel: string;
  fallbackWriterModel: string;
  abiBuilder: AbiBuilderService | undefined;
  executeToolAction: (
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
